function keywordWritePlan({ values, results, sheetName, start }) {
  if (!Array.isArray(values) || !Array.isArray(values[0]))
    throw new Error("The current keyword worksheet has no header row");
  if (!Array.isArray(results) || results.length < 1 || results.length > 6)
    throw new Error("Expected a complete classified batch");
  if (typeof sheetName !== "string" || !sheetName.trim())
    throw new Error("Configure the keyword worksheet name");
  const headers = values[0],
    key = headers.indexOf("Number"),
    target = headers.indexOf("Service?");
  if (key < 0 || target < 0) throw new Error("The worksheet needs Number and Service? headers");
  const column = (index) => {
    let label = "";
    for (let n = index + 1; n; n = Math.floor((n - 1) / 26))
      label = String.fromCharCode(65 + ((n - 1) % 26)) + label;
    return label;
  };
  const tab = "'" + sheetName.replace(/'/g, "''") + "'",
    data = [],
    unmatched = [];
  for (const result of results) {
    if (
      !result ||
      !Number.isInteger(result.index) ||
      !["string", "number", "boolean"].includes(typeof result.number) ||
      !["yes", "no"].includes(result.classification)
    )
      throw new Error("Invalid keyword classification or match key");
    const row = values.findIndex(
      (cells, index) =>
        index > 0 &&
        Array.isArray(cells) &&
        cells[key] !== null &&
        cells[key] !== undefined &&
        String(cells[key]) === String(result.number),
    );
    if (row < 0) unmatched.push(result.index);
    else
      data.push({
        range: tab + "!" + column(target) + (row + 1),
        values: [[result.classification]],
      });
  }
  return {
    data,
    hasUpdates: data.length > 0,
    expectedCells: data.length,
    unmatched,
    results,
    start,
    count: results.length,
  };
}

function keywordWriteReceipt({ results, start, count, expectedCells, unmatched, actualCells }) {
  if (
    !Array.isArray(results) ||
    results.length !== count ||
    !Number.isInteger(start) ||
    !Number.isInteger(count) ||
    count < 1 ||
    count > 6 ||
    !Array.isArray(unmatched) ||
    !Number.isInteger(expectedCells) ||
    expectedCells !== count - unmatched.length
  )
    throw new Error("Invalid keyword batch write plan");
  if (expectedCells > 0 && actualCells !== expectedCells)
    throw new Error(
      "Google Sheets did not confirm every planned Service? cell; check the worksheet before replaying this batch",
    );
  return { results, start, count, updated: expectedCells, unmatched };
}

export default function keywordImportProgress({
  rows,
  sheetName,
  previousState,
  modelResponse,
  currentValues,
  actualCells,
}) {
  if (!Array.isArray(rows)) throw new Error("Expected the complete original keyword rows");
  const fresh = previousState === null || previousState === undefined;
  const state = fresh
    ? {
        offset: 0,
        within: 0,
        stage: rows.length ? "wait" : "done",
        batchResults: [],
        results: [],
        batches: [],
        plan: null,
      }
    : previousState;
  if (
    !state ||
    !Number.isInteger(state.offset) ||
    state.offset < 0 ||
    state.offset > rows.length ||
    !Number.isInteger(state.within) ||
    state.within < 0 ||
    state.within > 6 ||
    !Array.isArray(state.batchResults) ||
    !Array.isArray(state.results) ||
    !Array.isArray(state.batches) ||
    !["wait", "classify", "refresh", "write", "done"].includes(state.stage)
  )
    throw new Error("Invalid keyword import state");
  const completeBatch = (receipt) => {
    state.results.push(...receipt.results);
    state.batches.push({
      start: receipt.start,
      count: receipt.count,
      updated: receipt.updated,
      unmatched: receipt.unmatched,
    });
    state.offset += receipt.count;
    state.within = 0;
    state.batchResults = [];
    state.plan = null;
    state.stage = state.offset < rows.length ? "wait" : "done";
  };
  if (!fresh) {
    if (state.stage === "wait") state.stage = "classify";
    else if (state.stage === "classify") {
      if (
        !modelResponse ||
        typeof modelResponse !== "object" ||
        !["yes", "no"].includes(modelResponse.Isservice)
      )
        throw new Error(
          "The classifier must return Isservice as yes or no; this batch has not been written",
        );
      const row = rows[state.offset + state.within];
      if (!row) throw new Error("Missing original keyword for this classification");
      state.batchResults.push({ ...row, classification: modelResponse.Isservice });
      state.within += 1;
      state.stage =
        state.within === Math.min(6, rows.length - state.offset) ? "refresh" : "classify";
    } else if (state.stage === "refresh") {
      state.plan = keywordWritePlan({
        values: currentValues,
        results: state.batchResults,
        sheetName,
        start: state.offset,
      });
      if (state.plan.hasUpdates) state.stage = "write";
      else completeBatch(keywordWriteReceipt({ ...state.plan, actualCells: null }));
    } else if (state.stage === "write")
      completeBatch(keywordWriteReceipt({ ...state.plan, actualCells }));
    else throw new Error("A completed keyword import must not be restarted inside the same run");
  }
  const row = rows[state.offset + state.within];
  return {
    state,
    phase: state.stage,
    prompt: state.stage === "classify" ? "keyword: " + row.keyword : "",
    data: state.plan?.data ?? [],
    results: state.results,
    batches: state.batches,
    count: state.results.length,
  };
}

